class BasicPlan extends Subscription {
    BasicPlan(int m){
        super(m);
    }
    @Override
    double calculateCost(){
        return months*199;
    }
}

class PremiumPlan extends Subscription {
    PremiumPlan(int m){
        super(m);
    }
    @Override
    double calculateCost(){
        return months*499;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        try {
            String planType = sc.nextLine();
            int months = Integer.parseInt(sc.nextLine());

            if(months < 0){
                throw new NumberFormatException();
            }

            Subscription sub;
            if (planType.equals("Basic")) {
                sub = new BasicPlan(months);
            } else if (planType.equals("Premium")) {
                sub = new PremiumPlan(months);
            } else {
                System.out.println("Invalid Input");
                return;
            }

            sub.displayMonths();
            System.out.println("Total Cost: " + sub.calculateCost());
        } catch (NumberFormatException e) {
            System.out.println("Invalid Input");
        }
        sc.close();
    }
}

